class Solution {
    public int longestConsecutive(int[] nums) {
        int res = 1;
        Set<Integer> set = new HashSet<>();
        for(int i = 0;i<nums.length;i++){
            set.add(nums[i]);
        }
        if(nums==null || nums.length==0){
            return 0;
        }
        for(int num:set){
            int x = num;
            if(set.contains(x-1))
            continue;
            int y = x+1;
            while(set.contains(y)){
                res = Math.max(res,y-x+1);
                y++;
            }
        }
        return res;
    }
}
